#pragma once
// The test lines of the rules program, each a unit test generated by hdrulec tests: one
// line translated as a document with the dictionaries in HDTRANS_DICTS (skipped when
// unset). A failure names the rule and the test line.
namespace ruletests {

enum class Kind { Text, Unchanged, Picks, Silent };

struct Case {
    char kind;       // 'L' or 'G'
    int index;       // record index
    int number;      // global rule number
    const char* file;
    int line;        // of the test line
    Kind test;
    const char* input;
    const char* expected;
};

void Run(const Case& c);

}  // namespace ruletests
